module hr_optimization (input clk, input rst_n, input start, input [5:0] hire_count, input [5:0] fire_count, input valid_in, input last_day, output reg [2:0] hr_id_out, output reg [3:0] day_index_out, output reg valid_out, output reg [2:0] min_hr_count, output reg done); reg [2:0] state_reg; reg [6:0] stack_ptr; reg [3:0] day_index; reg [2:0] max_hr_id; reg [2:0] min_id_reg; reg [63:0] worker_stack; reg [7:0] fired_ids; parameter IDLE = 3'd0; parameter READ_DAY = 3'd1; parameter PROCESS_FIRE = 3'd2; parameter PROCESS_HIRE = 3'd3; parameter UPDATE_OUT = 3'd4; parameter CHECK_DONE = 3'd5; always @(*) begin next_state = state_reg; case (state_reg) IDLE: if (start) next_state = READ_DAY; READ_DAY: if (valid_in) next_state = PROCESS_FIRE; PROCESS_FIRE: next_state = PROCESS_HIRE; PROCESS_HIRE: next_state = UPDATE_OUT; UPDATE_OUT: next_state = CHECK_DONE; CHECK_DONE: if (!last_day) next_state = READ_DAY; endcase end always @(posedge clk) begin if (!rst_n) begin state_reg <= IDLE; stack_ptr <= 0; day_index <= 0; max_hr_id <= 0; min_id_reg <= 0; end else begin state_reg <= next_state; case (next_state) PROCESS_HIRE: begin stack_ptr <= stack_ptr - fire_count + hire_count; min_id_reg <= 1; if (1 > max_hr_id) max_hr_id <= 1; end UPDATE_OUT: begin hr_id_out <= min_id_reg; day_index_out <= day_index; valid_out <= 1'b1; end CHECK_DONE: begin if (!last_day) day_index <= day_index +1; done <= last_day; end endcase end end always @(*) begin if (state_reg == PROCESS_FIRE) begin fired_ids[0] = (fire_count >0) ? worker_stack[stack_ptr-1] : 0; end end assign min_hr_count = max_hr_id; endmodule